    private FrameLayout createBackground(Context context) {
        FrameLayout frameLayout = new FrameLayout(context);
        frameLayout.setLayoutParams(new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
        ));

        initBackground(context, frameLayout);

        return frameLayout;
    }

    private void initBackground(Context context, FrameLayout frameLayout) {
        this.backgroundImage = new BackupImageView(context);
        this.backgroundImage.setAspectFit(false);
        this.backgroundImage.setLayoutParams(new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
        ));

        motionBackgroundDrawable = new MotionBackgroundDrawable();

        this.backgroundImage.getImageReceiver().setDelegate(new ImageReceiver.ImageReceiverDelegate() {
            @Override
            public void didSetImage(ImageReceiver imageReceiver, boolean set, boolean thumb, boolean memCache) {
                if (imageReceiver.getBitmap() != null) {
                    int dominant = ImageHelper.getDominantColor(imageReceiver.getBitmap());
                    int darkened = ImageHelper.darkenColor(dominant, 0.4f);
                    motionBackgroundDrawable.setColors(dominant, darkened, dominant, darkened);
                    return;
                }
                motionBackgroundDrawable.setColors(0xff333333, 0xff000000, 0xff333333, 0xff000000);
            }

            @Override
            public void didSetImageBitmap(int i, String s, Drawable drawable) {
                if (drawable instanceof BitmapDrawable) {
                    int dominant = ImageHelper.getDominantColor((BitmapDrawable) drawable);
                    int darkened = ImageHelper.darkenColor(dominant, 0.4f);
                    motionBackgroundDrawable.setColors(dominant, darkened, dominant, darkened);
                    return;
                }
                motionBackgroundDrawable.setColors(0xff333333, 0xff000000, 0xff333333, 0xff000000);
            }

            @Override
            public void onAnimationReady(ImageReceiver imageReceiver) {
            }
        });

        FrameLayout overlayFrame = new FrameLayout(context);
        overlayFrame.setBackground(motionBackgroundDrawable);
        overlayFrame.setLayoutParams(new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT
        ));

        frameLayout.addView(this.backgroundImage);
        frameLayout.addView(overlayFrame);
    }

    private void createPlaylist(Context context, LinearLayout main_layout) {
        for (MessageObject message : playlist) {
            LinearLayout trackItem = createTrackItemView(context, message);
            main_layout.addView(trackItem);
        }
        updatePlaylistSelection();
    }

    private void updatePlaylistSelection() {
        MessageObject currentPlaying = MediaController.getInstance().getPlayingMessageObject();
        for (TrackItemHolder holder : playlistView) {
            boolean isPlaying = (holder.message == currentPlaying);
            if (isPlaying) {
                holder.title.setTypeface(null, Typeface.BOLD);
                holder.title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText));
                holder.author.setTypeface(null, Typeface.BOLD);
                holder.author.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText));
                holder.duration.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText));
            } else {
                holder.title.setTypeface(null, Typeface.NORMAL);
                holder.title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText));
                holder.author.setTypeface(null, Typeface.NORMAL);
                holder.author.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));
                holder.duration.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));
                holder.playingIcon.setVisibility(View.GONE);
            }
        }
    }

    private LinearLayout createTrackItemView(Context context, MessageObject message) {
        LinearLayout itemView = new LinearLayout(context);
        itemView.setOrientation(LinearLayout.HORIZONTAL);
        itemView.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(12),
                AndroidUtilities.dp(12), AndroidUtilities.dp(12));
        itemView.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector)));
        itemView.setLayoutParams(new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
        ));

        // Обложка
        BackupImageView cover = new CoverLayout(context);
        cover.setLayoutParams(new LinearLayout.LayoutParams(AndroidUtilities.dp(48), AndroidUtilities.dp(48)));
        cover.setRoundRadius(AndroidUtilities.dp(12));
        cover.setAspectFit(true);
        itemView.addView(cover);

        // Контейнер для текста
        LinearLayout textContainer = new LinearLayout(context);
        textContainer.setOrientation(LinearLayout.VERTICAL);
        textContainer.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        textContainer.setPadding(AndroidUtilities.dp(12), 0, AndroidUtilities.dp(12), 0);

        TextView title = new TextView(context);
        title.setTextSize(16);
        title.setTypeface(null, Typeface.BOLD);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.END);
        textContainer.addView(title);

        TextView author = new TextView(context);
        author.setTextSize(14);
        author.setSingleLine(true);
        author.setEllipsize(TextUtils.TruncateAt.END);
        author.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));
        textContainer.addView(author);

        itemView.addView(textContainer);

        // Длительность
        TextView duration = new TextView(context);
        duration.setTextSize(14);
        duration.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));
        duration.setGravity(Gravity.END | Gravity.CENTER_VERTICAL);
        duration.setLayoutParams(new LinearLayout.LayoutParams(AndroidUtilities.dp(60), ViewGroup.LayoutParams.WRAP_CONTENT));
        itemView.addView(duration);

        // Иконка воспроизведения
        RLottieImageView playingIcon = new RLottieImageView(context);
        playingIcon.setScaleType(ImageView.ScaleType.CENTER);
        playingIcon.setLayoutParams(new LinearLayout.LayoutParams(AndroidUtilities.dp(24), AndroidUtilities.dp(24)));
        playingIcon.setVisibility(View.GONE);
        itemView.addView(playingIcon);

        // Заполняем данными
        MusicInfo info = new MusicInfo(message);
        ImageHelper.updateCover(message, cover, false);
        title.setText(info.getCurrentTitle());
        author.setText(info.getCurrentAuthor());
        duration.setText(info.getAudioProgressString());

        // Создаём холдер и сохраняем в список
        TrackItemHolder holder = new TrackItemHolder(itemView, cover, title, author, duration, playingIcon, message);
        playlistView.add(holder);

        // Клик по элементу
        itemView.setOnClickListener(v -> {
            MediaController.getInstance().playMessage(message);
            if (playPauseDrawable != null) {
                playPauseDrawable.setPause(!MediaController.getInstance().isMessagePaused(), false);
            }
            updatePlaylistSelection();
            if (manager != null) manager.updateUI();
        });

        return itemView;
    }

    private void renderError(FrameLayout container, Context context) {
        TextView textView = new TextView(context);
        textView.setText(MusicPlayer.getInstance().getString("no_music"));
        textView.setTextSize(24);
        textView.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText));
        textView.setGravity(Gravity.CENTER);

        container.addView(textView, LayoutHelper.createFrame(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT,
                Gravity.CENTER));

    }

    private static class ControlsElement {
        private Runnable runnable;
        private int iconId;
        private boolean isAnimation;

        public ControlsElement(Runnable runnable, int iconId, boolean isAnimation) {
            this.runnable = runnable;
            this.iconId = iconId;
            this.isAnimation = isAnimation;
        }

        public Runnable getRunnable() {
            return runnable;
        }

        public void setRunnable(Runnable runnable) {
            this.runnable = runnable;
        }

        public int getIconId() {
            return iconId;
        }

        public void setIconId(int iconId) {
            this.iconId = iconId;
        }

        public boolean isAnimation() {
            return isAnimation;
        }

        public void setAnimation(boolean animation) {
            isAnimation = animation;
        }
    }

    private static class TrackItemHolder {
        LinearLayout container;
        BackupImageView cover;
        TextView title;
        TextView author;
        TextView duration;
        RLottieImageView playingIcon;
        MessageObject message;

        TrackItemHolder(LinearLayout container, BackupImageView cover, TextView title,
                        TextView author, TextView duration, RLottieImageView playingIcon,
                        MessageObject message) {
            this.container = container;
            this.cover = cover;
            this.title = title;
            this.author = author;
            this.duration = duration;
            this.playingIcon = playingIcon;
            this.message = message;
        }
    }
}

package ru.hoprik.player.utils;

import android.graphics.Bitmap;
import android.graphics.Color;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.os.Looper;
import android.widget.SeekBar;
import android.widget.TextView;
import org.telegram.messenger.ImageReceiver;
import org.telegram.messenger.MediaController;
import org.telegram.ui.ActionBar.SimpleTextView;
import org.telegram.ui.Components.BackupImageView;
import ru.hoprik.player.MusicPlayer;

public class UpdateManager {

    private MusicInfo info;
    private SimpleTextView songNameView;
    private TextView authorName;
    private BackupImageView avatarView;
    private BackupImageView backgroundView;
    private GradientDrawable overlayColor;
    private TextView currentDurationView;
    private TextView audioTimeView;
    private SeekBar seekBar;
    private boolean isDragging;

    private final Handler handler = new Handler(Looper.getMainLooper());
    private Runnable updateRunnable;
    private boolean isRunning = false;

    public UpdateManager(MusicInfo info, SimpleTextView songNameView, TextView authorName, BackupImageView avatarView, BackupImageView backgroundView, GradientDrawable overlayColor, TextView currentDurationView, TextView audioTimeView, SeekBar seekBar) {
        this.info = info;
        this.songNameView = songNameView;
        this.authorName = authorName;
        this.avatarView = avatarView;
        this.backgroundView = backgroundView;
        this.overlayColor = overlayColor;
        this.currentDurationView = currentDurationView;
        this.audioTimeView = audioTimeView;
        this.seekBar = seekBar;
    }

    public void startUpdater() {
        if (isRunning) return;

        updateRunnable = new Runnable() {
            @Override
            public void run() {
                updateUI();
                if (isRunning) {
                    handler.postDelayed(this, 1000);
                }
            }
        };

        isRunning = true;
        handler.post(updateRunnable);
    }

    public void stopUpdater() {
        isRunning = false;
        if (updateRunnable != null) {
            handler.removeCallbacks(updateRunnable);
            updateRunnable = null;
        }
    }

    public void updateUI() {
        info.update(MediaController.getInstance().getPlayingMessageObject());

        if (info.isShouldUpdate()) {
            songNameView.setText(info.getCurrentTitle());
            authorName.setText(info.getCurrentAuthor());
            ImageHelper.updateCover(info.getMessageObject(), avatarView, false);
            ImageHelper.updateCover(info.getMessageObject(), backgroundView, true);

            backgroundView.getImageReceiver().setDelegate(new ImageReceiver.ImageReceiverDelegate() {
                @Override
                public void didSetImage(ImageReceiver imageReceiver, boolean set, boolean thumb, boolean memCache) {
                    if (MusicPlayer.getInstance().isFeatureEnabled("enable_background_dominant", true)) {
                        if (imageReceiver.getBitmap() != null) {
                            applyColors(imageReceiver.getBitmap(), overlayColor);
                            return;
                        }
                        overlayColor.setColors(new int[]{Color.parseColor("#525252"), ImageHelper.darkenColor(Color.parseColor("#525252"), 0.6f)});
                    }
                }

                @Override
                public void didSetImageBitmap(int i, String s, Drawable drawable) {
                    if (MusicPlayer.getInstance().isFeatureEnabled("enable_background_dominant", true)) {
                        if (drawable instanceof BitmapDrawable) {
                            applyColors(((BitmapDrawable) drawable).getBitmap(), overlayColor);
                            return;
                        }
                        overlayColor.setColors(new int[]{Color.parseColor("#525252"), ImageHelper.darkenColor(Color.parseColor("#525252"), 0.6f)});
                    }
                }

                @Override
                public void onAnimationReady(ImageReceiver imageReceiver) {
                }
            });
        }

        if (!isDragging) {
            currentDurationView.setText(info.getTimeString());
            audioTimeView.setText(info.getAudioProgressString());

            long current = info.getCurrentDuration();
            long total = info.getAudioProgress();

            if (total > 0) {
                int progress = (int) (((float) current / total) * 100);
                seekBar.setProgress(progress);
            } else {
                seekBar.setProgress(0);
            }
        }
    }

    private void applyColors(Bitmap bitmap, GradientDrawable overlayColor) {
        if (overlayColor == null) return;
        int dominant = ImageHelper.getDominantColor(bitmap);
        overlayColor.setColors(new int[]{dominant, ImageHelper.darkenColor(dominant, 0.6f)});
    }

    public void setDragging(boolean dragging) {
        isDragging = dragging;
    }

    public boolean isDragging() {
        return isDragging;
    }
}

package ru.hoprik.player.utils;

import android.graphics.Bitmap;
import android.graphics.Color;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.os.Looper;
import android.widget.SeekBar;
import android.widget.TextView;
import org.telegram.messenger.ImageReceiver;
import org.telegram.messenger.MediaController;
import org.telegram.ui.ActionBar.SimpleTextView;
import org.telegram.ui.Components.BackupImageView;
import ru.hoprik.player.MusicPlayer;

public class UpdateManager {

    private MusicInfo info;
    private SimpleTextView songNameView;
    private TextView authorName;
    private BackupImageView avatarView;
    private BackupImageView backgroundView;
    private GradientDrawable overlayColor;
    private TextView currentDurationView;
    private TextView audioTimeView;
    private SeekBar seekBar;
    private boolean isDragging;

    private final Handler handler = new Handler(Looper.getMainLooper());
    private Runnable updateRunnable;
    private boolean isRunning = false;

    public UpdateManager(MusicInfo info, SimpleTextView songNameView, TextView authorName, BackupImageView avatarView, BackupImageView backgroundView, GradientDrawable overlayColor, TextView currentDurationView, TextView audioTimeView, SeekBar seekBar) {
        this.info = info;
        this.songNameView = songNameView;
        this.authorName = authorName;
        this.avatarView = avatarView;
        this.backgroundView = backgroundView;
        this.overlayColor = overlayColor;
        this.currentDurationView = currentDurationView;
        this.audioTimeView = audioTimeView;
        this.seekBar = seekBar;
    }

    public void startUpdater() {
        if (isRunning) return;

        updateRunnable = new Runnable() {
            @Override
            public void run() {
                updateUI();
                if (isRunning) {
                    handler.postDelayed(this, 1000);
                }
            }
        };

        isRunning = true;
        handler.post(updateRunnable);
    }

    public void stopUpdater() {
        isRunning = false;
        if (updateRunnable != null) {
            handler.removeCallbacks(updateRunnable);
            updateRunnable = null;
        }
    }

    public void updateUI() {
        info.update(MediaController.getInstance().getPlayingMessageObject());

        if (info.isShouldUpdate()) {
            songNameView.setText(info.getCurrentTitle());
            authorName.setText(info.getCurrentAuthor());
            ImageHelper.updateCover(info.getMessageObject(), avatarView, false);
            ImageHelper.updateCover(info.getMessageObject(), backgroundView, true);
        }

        if (!isDragging) {
            currentDurationView.setText(info.getTimeString());
            audioTimeView.setText(info.getAudioProgressString());

            long current = info.getCurrentDuration();
            long total = info.getAudioProgress();

            if (total > 0) {
                int progress = (int) (((float) current / total) * 100);
                seekBar.setProgress(progress);
            } else {
                seekBar.setProgress(0);
            }
        }
    }

    private void applyColors(Bitmap bitmap, GradientDrawable overlayColor) {
        if (overlayColor == null) return;
        int dominant = ImageHelper.getDominantColor(bitmap);
        overlayColor.setColors(new int[]{dominant, ImageHelper.darkenColor(dominant, 0.6f)});
    }

    public void setDragging(boolean dragging) {
        isDragging = dragging;
    }

    public boolean isDragging() {
        return isDragging;
    }
}
